// Tests for the vendored Unreal Angelscript TextMate grammar used by the web
// file viewer (shiki) and the desktop diff editors (shiki inside Monaco).
// The grammar is generated by scripts/syntax/vendor-angelscript-grammar.mjs
// into two mirrored copies; these tests check they match and tokenize as
// expected.

import { describe, it, expect, beforeAll } from "vitest";
import fs from "node:fs";
import path from "node:path";
import { createHighlighter, type Highlighter } from "shiki";

const repoRoot = path.resolve(__dirname, "../../../..");
const APP_COPY = path.join(repoRoot, "src/app/src/lib/syntax/angelscript.tmLanguage.json");
const DESKTOP_COPY = path.join(repoRoot, "src/clients/desktop/src/renderer/syntax/angelscript.tmLanguage.json");

let highlighter: Highlighter;

beforeAll(async () => {
  const grammar = JSON.parse(fs.readFileSync(APP_COPY, "utf-8"));
  highlighter = await createHighlighter({ themes: ["github-dark-default"], langs: [grammar] });
});

/** Returns the innermost scope of every non-whitespace token on one line. */
function scopesOf(code: string): Array<[string, string]> {
  const { tokens } = highlighter.codeToTokens(code, {
    lang: "angelscript",
    theme: "github-dark-default",
    includeExplanation: true,
  });
  const out: Array<[string, string]> = [];
  for (const line of tokens) {
    for (const token of line) {
      for (const part of token.explanation ?? []) {
        const text = part.content.trim();
        if (!text) continue;
        out.push([text, part.scopes.at(-1)!.scopeName]);
      }
    }
  }
  return out;
}

function scopeOf(code: string, word: string): string | undefined {
  return scopesOf(code).find(([text]) => text === word)?.[1];
}

describe("angelscript grammar copies", () => {
  it("keeps the app and desktop copies identical", () => {
    expect(fs.readFileSync(DESKTOP_COPY, "utf-8")).toBe(fs.readFileSync(APP_COPY, "utf-8"));
  });

  it("registers under the angelscript language id", () => {
    expect(highlighter.getLoadedLanguages()).toContain("angelscript");
  });
});

describe("angelscript keywords and literals", () => {
  it.each([
    ["class AFoo : AActor {}", "class", "keyword.declaration.angelscript"],
    ["if (x) return;", "if", "keyword.statement.angelscript"],
    ["if (x) return;", "return", "keyword.statement.angelscript"],
    ["while(x) {}", "while", "keyword.statement.angelscript"],
    ["const int X = 1;", "const", "keyword.type.angelscript"],
    ["int32 X = 1;", "int32", "storage.type.primitive.angelscript"],
    ["Super::BeginPlay();", "Super", "keyword.code.angelscript"],
    ["auto P = Cast<APawn>(O);", "Cast", "keyword.code.angelscript"],
    ["X = nullptr;", "nullptr", "keyword.code.angelscript.nullptr.reference"],
  ])("%s: %s is %s", (code, word, scope) => {
    expect(scopeOf(code, word)).toBe(scope);
  });

  it("colors float literals as numbers", () => {
    const scopes = scopesOf("X = 1.5f;");
    expect(scopes.find(([text]) => text === "1")?.[1]).toMatch(/numeric/);
    expect(scopes.find(([text]) => text === "f")?.[1]).toMatch(/suffix/);
  });

  it("colors the n prefix of name literals and keeps the body a string", () => {
    const scopes = scopesOf('FName N = n"Enemy";');
    expect(scopes).toContainEqual(["n", "storage.type.string.name.angelscript"]);
    expect(scopes).toContainEqual(["Enemy", "string.quoted.double.name.angelscript"]);
  });

  it("highlights format string expressions", () => {
    expect(scopeOf('Print(f"Dist {Dist}");', "{")).toBe("keyword.formatexpression.angelscript");
  });

  it("colors &in / &out / &inout parameter modifiers", () => {
    const code = "void F(int&out A, const FHitResult&in B, int&inout C) {}";
    expect(scopeOf(code, "out")).toBe("keyword.type.angelscript");
    expect(scopeOf(code, "in")).toBe("keyword.type.angelscript");
    expect(scopeOf(code, "inout")).toBe("keyword.type.angelscript");
  });

  it("does not treat in/out as keywords outside a reference parameter", () => {
    expect(scopeOf("int out = in;", "out")).not.toBe("keyword.type.angelscript");
  });

  it("leaves keywords inside comments as comments", () => {
    expect(scopeOf("// if (x) UFUNCTION()", "if")).toBeUndefined();
    expect(scopesOf("// if (x)").every(([, s]) => s.startsWith("comment") || s.startsWith("punctuation.definition.comment"))).toBe(true);
  });
});

describe("angelscript Unreal macros", () => {
  it("colors the macro name and its specifiers", () => {
    const code = 'UPROPERTY(EditAnywhere, Category = "Stuff")';
    expect(scopeOf(code, "UPROPERTY")).toBe("variable.other.enummember");
    expect(scopeOf(code, "EditAnywhere")).toBe("keyword.specifier.angelscript");
    expect(scopeOf(code, "Stuff")).toBe("string.quoted.double.angelscript");
  });

  it("does not color a macro as a function call", () => {
    expect(scopeOf("UFUNCTION(BlueprintOverride)", "UFUNCTION")).not.toBe("entity.name.function.angelscript");
  });
});

describe("angelscript type-name heuristics", () => {
  it.each([
    ["UStaticMeshComponent Mesh;", "UStaticMeshComponent", "support.type.component.angelscript"],
    ["AMyActor Actor;", "AMyActor", "support.type.actor.angelscript"],
    ["FVector V;", "FVector", "support.type.struct.angelscript"],
    ["ECollisionChannel C;", "ECollisionChannel", "support.type.enum.angelscript"],
    ["UObject O;", "UObject", "support.type.angelscript"],
    ["TArray<int> A;", "TArray", "support.type.angelscript"],
    ["auto P = Cast<APawn>(O);", "APawn", "support.type.actor.angelscript"],
    ["FVector V = FVector(1, 2, 3);", "FVector", "support.type.struct.angelscript"],
  ])("%s: %s is %s", (code, word, scope) => {
    expect(scopeOf(code, word)).toBe(scope);
  });

  it.each(["MAX_COUNT", "EXIT_CODE", "UNUSED", "Actor", "Foo"])("does not treat %s as a type", (word) => {
    expect(scopeOf(`int ${word} = 1;`, word)).toBe("source.angelscript");
  });

  it("colors the enum scope before :: as a type, not a namespace", () => {
    expect(scopeOf("X = ECollisionChannel::ECC_Visibility;", "ECollisionChannel")).toBe("support.type.enum.angelscript");
  });

  it("colors a plain namespace before ::", () => {
    expect(scopeOf("float D = Math::Abs(X);", "Math")).toBe("entity.name.namespace.angelscript");
  });
});

describe("angelscript function names", () => {
  it.each([
    ["void BeginPlay() {}", "BeginPlay"],
    ["Super::BeginPlay();", "BeginPlay"],
    ["float D = Math::Abs(X);", "Abs"],
    ["GetActorLocation().X", "GetActorLocation"],
    ["Print (X);", "Print"],
  ])("%s: %s is a function", (code, word) => {
    expect(scopeOf(code, word)).toBe("entity.name.function.angelscript");
  });

  it.each(["if", "while", "for", "switch", "return"])("keeps %s ( as a keyword", (kw) => {
    expect(scopeOf(`${kw} (x)`, kw)).toMatch(/^keyword\./);
  });
});
